import fs from 'node:fs';
import path from 'node:path';
import * as GeoTIFF from 'geotiff';
import { GeoTiffService } from 'd:/tn-enforcement-system/tn-forest-monitoring/server/src/services/raster/GeoTiffService.js';

async function inspectFile(label: string, filePath: string) {
  console.log(`\n======================================================`);
  console.log(`🔍 INSPECTING ${label}`);
  console.log(`Path: ${filePath}`);
  if (!fs.existsSync(filePath)) {
    console.log(`❌ FILE DOES NOT EXIST!`);
    return;
  }
  const stat = fs.statSync(filePath);
  console.log(`Size: ${stat.size} bytes (${(stat.size / 1024 / 1024).toFixed(2)} MB)`);

  const buffer = fs.readFileSync(filePath);
  const arrayBuffer = buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength);
  const tiff = await GeoTIFF.fromArrayBuffer(arrayBuffer);
  const image = await tiff.getImage();

  const width = image.getWidth();
  const height = image.getHeight();
  const numBands = image.getSamplesPerPixel();
  const nodata = image.getGDALNoData();
  const origin = image.getOrigin();
  const resolution = image.getResolution();
  const bbox = image.getBoundingBox();
  const geoKeys = typeof image.getGeoKeys === 'function' ? image.getGeoKeys() : (image as any).geoKeys;
  const fileDir = image.fileDirectory as any;
  const bitsPerSample = image.getBitsPerSample();
  const sampleFormat = image.getSampleFormat();

  console.log(`Dimensions: ${width} × ${height}`);
  console.log(`Samples per pixel (Bands): ${numBands}`);
  console.log(`Bits per sample:`, bitsPerSample);
  console.log(`Sample format:`, sampleFormat);
  console.log(`GDAL NoData:`, nodata);
  console.log(`Origin:`, origin);
  console.log(`Resolution:`, resolution);
  console.log(`BoundingBox:`, bbox);
  console.log(`GeoKeys:`, JSON.stringify(geoKeys));
  console.log(`GeoAsciiParamsTag:`, fileDir?.GeoAsciiParamsTag || fileDir?.GeoAsciiParams);

  const parsed = await GeoTiffService.readGeoTiffFromBuffer(buffer);
  console.log(`Parsed Metadata:`, parsed.metadata);
  console.log(`Parsed Band count:`, parsed.bandData.length);

  for (let b = 0; b < parsed.bandData.length; b++) {
    const band = parsed.bandData[b];
    let min = Infinity;
    let max = -Infinity;
    let nonZero = 0;
    let nanCount = 0;
    let sum = 0;

    for (let i = 0; i < band.length; i++) {
      const v = band[i];
      if (isNaN(v)) {
        nanCount++;
        continue;
      }
      if (v < min) min = v;
      if (v > max) max = v;
      if (v !== 0) nonZero++;
      sum += v;
    }
    const mean = nonZero > 0 ? sum / nonZero : 0;
    console.log(`  Band ${b}: min=${min}, max=${max}, meanNonZero=${mean.toFixed(2)}, nonZeroPixels=${nonZero}/${band.length}, NaNs=${nanCount}`);

    // Print first 10 pixel values
    const firstTen = Array.from(band.slice(0, 10));
    console.log(`    First 10 values: [${firstTen.join(', ')}]`);
    // Print 10 middle pixel values
    const mid = Math.floor(band.length / 2);
    const midTen = Array.from(band.slice(mid, mid + 10));
    console.log(`    Mid 10 values: [${midTen.join(', ')}]`);
  }

  // Test rendering
  try {
    const pngBuf = await GeoTiffService.renderTrueColorPngFromBuffer(buffer);
    console.log(`Rendered PNG: ${pngBuf.length} bytes`);
    const outPng = path.join('C:/Users/jayaseelan/.gemini/antigravity/brain/0fa06343-02c9-4e30-bff2-c98f7b170b82/scratch', `${label.replace(/[^a-zA-Z0-9]/g, '_')}.png`);
    fs.writeFileSync(outPng, pngBuf);
    console.log(`Wrote debug PNG to ${outPng}`);
  } catch (err) {
    console.error(`Rendering failed:`, err);
  }
}

async function main() {
  const landsatBaseline = 'D:/tn-enforcement-system/tn-forest-monitoring/server/storage/raster_temp/6aa679012b4fe5808c7e8ec7/ZONE-260913-7787_6aa679012b4fe5808c7e8ec7_BASELINE_Landsat8_20150106.tif';
  const landsatCurrent = 'D:/tn-enforcement-system/tn-forest-monitoring/server/storage/raster_temp/6aa678502b4fe5808c7e8e2d/ZONE-260913-7787_6aa678502b4fe5808c7e8e2d_CURRENT_Landsat8_20150106.tif';
  const sentinelCurrent = 'D:/tn-enforcement-system/tn-forest-monitoring/server/storage/raster_temp/6aa6798c2b4fe5808c7e9038/ZONE-260913-7787_6aa6798c2b4fe5808c7e9038_CURRENT_Sentinel2_20260909.tif';

  await inspectFile('LANDSAT_BASELINE', landsatBaseline);
  await inspectFile('LANDSAT_CURRENT', landsatCurrent);
  await inspectFile('SENTINEL2_CURRENT', sentinelCurrent);
}

main().catch(console.error);
